$type=(string)($_GET['type']??$_POST['report_type']??'sales');if(!isset(ManagementReportsRepository::TYPES[$type]))$type='sales';$template=ManagementReportsRepository::template($type,false);if(!$template){http_response_code(503);exit('قالب گزارش راه‌اندازی نشده است.');}
