    try{$action=(string)($_POST['action']??'');
        if($action==='template'){$title=trim((string)($_POST['title']??''));if($title==='')throw new InvalidArgumentException('عنوان قالب الزامی است.');Database::execute('UPDATE management_report_templates SET title=?,description=?,active=?,updated_by=?,updated_at=NOW() WHERE id=?',[$title,trim((string)($_POST['description']??'')),isset($_POST['active'])?1:0,(int)Auth::user()['id'],(int)$template['id']]);$record=(int)$template['id'];$message='تنظیمات قالب ذخیره شد.';}
        elseif($action==='section'){$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$key=trim((string)($_POST['section_key']??''));if($title===''||!preg_match('/^[a-z][a-z0-9_]{1,99}$/',$key))throw new InvalidArgumentException('عنوان و کلید انگلیسی معتبر برای بخش الزامی است.');if(Database::fetch('SELECT id FROM management_report_sections WHERE template_id=? AND section_key=? AND id<>?',[(int)$template['id'],$key,$id]))throw new InvalidArgumentException('کلید بخش تکراری است.');$data=[$key,$title,trim((string)($_POST['description']??'')),(int)($_POST['sort_order']??0),isset($_POST['active'])?1:0];if($id){if(!Database::fetch('SELECT id FROM management_report_sections WHERE id=? AND template_id=?',[$id,(int)$template['id']]))throw new InvalidArgumentException('بخش معتبر نیست.');Database::execute('UPDATE management_report_sections SET section_key=?,title=?,description=?,sort_order=?,active=?,updated_at=NOW() WHERE id=?',[...$data,$id]);$record=$id;}else{Database::execute('INSERT INTO management_report_sections(template_id,section_key,title,description,sort_order,active,created_at,updated_at) VALUES(?,?,?,?,?,?,NOW(),NOW())',[(int)$template['id'],...$data]);$record=(int)Database::lastInsertId();}$message='بخش گزارش ذخیره شد.';}
        elseif($action==='field'){$id=(int)($_POST['id']??0);$sectionId=(int)($_POST['section_id']??0);if(!Database::fetch('SELECT s.id FROM management_report_sections s WHERE s.id=? AND s.template_id=?',[$sectionId,(int)$template['id']]))throw new InvalidArgumentException('بخش انتخاب‌شده معتبر نیست.');$key=trim((string)($_POST['field_key']??''));$label=trim((string)($_POST['label']??''));$fieldType=(string)($_POST['field_type']??'text');if($label===''||!preg_match('/^[a-z][a-z0-9_]{1,99}$/',$key)||!isset(ManagementReportsRepository::FIELD_TYPES[$fieldType]))throw new InvalidArgumentException('عنوان، کلید و نوع فیلد معتبر الزامی است.');if(Database::fetch('SELECT id FROM management_report_fields WHERE section_id=? AND field_key=? AND id<>?',[$sectionId,$key,$id]))throw new InvalidArgumentException('کلید فیلد در این بخش تکراری است.');$linked=trim((string)($_POST['linked_source_key']??''));if($linked!==''&&!preg_match('/^[a-z][a-z0-9_.-]{1,189}$/',$linked))throw new InvalidArgumentException('کلید اتصال منبع داده معتبر نیست.');$optionsText=trim((string)($_POST['options']??''));$options=null;if($optionsText!==''){$decoded=json_decode($optionsText,true);$options=json_last_error()===JSON_ERROR_NONE?$decoded:array_values(array_filter(array_map('trim',preg_split('/\R/u',$optionsText))));}$data=[$sectionId,$key,$label,$fieldType,trim((string)($_POST['placeholder']??'')),trim((string)($_POST['help_text']??'')),$options!==null?json_encode($options,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null,trim((string)($_POST['default_value']??'')),$linked?:null,isset($_POST['is_required'])?1:0,(int)($_POST['sort_order']??0),isset($_POST['active'])?1:0];if($id){if(!Database::fetch('SELECT f.id FROM management_report_fields f JOIN management_report_sections s ON s.id=f.section_id WHERE f.id=? AND s.template_id=?',[$id,(int)$template['id']]))throw new InvalidArgumentException('فیلد معتبر نیست.');Database::execute('UPDATE management_report_fields SET section_id=?,field_key=?,label=?,field_type=?,placeholder=?,help_text=?,options_json=?,default_value=?,linked_source_key=?,is_required=?,sort_order=?,active=?,updated_at=NOW() WHERE id=?',[...$data,$id]);$record=$id;}else{Database::execute('INSERT INTO management_report_fields(section_id,field_key,label,field_type,placeholder,help_text,options_json,default_value,linked_source_key,is_required,sort_order,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())',$data);$record=(int)Database::lastInsertId();}$message='فیلد گزارش ذخیره شد.';}
        else throw new InvalidArgumentException('عملیات تنظیمات معتبر نیست.');Auth::log((int)Auth::user()['id'],'management_report_'.$action.'_saved','management_report_'.$action.'s',$record);flash($message);
    }catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Management report settings: '.$e->getMessage());flash('ذخیره تنظیمات قالب انجام نشد.','danger');}
    redirect('/admin/management-report-template-settings.php?type='.$type);
}
